css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.12;letter-spacing:-.02em}
p{margin:0}a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px}
section{padding:88px 0}
.dark{background:var(--k);color:#fff}.dark2{background:var(--k2);color:#fff}.grey{background:var(--g)}
.dark p,.dark2 p{color:var(--dmute)}
.sh{max-width:640px;margin-bottom:44px}
.sh h2{font-size:clamp(28px,4vw,42px)}
.sh p{margin-top:14px;color:var(--mute);font-size:17px}
.dark .sh p,.dark2 .sh p{color:var(--dmute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}
.b-l{background:var(--l);color:var(--k)}
.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}
.b-d{background:var(--k);color:#fff}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
nav{position:sticky;top:0;z-index:20;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-size:14.5px;color:#d0d0d4}
nav ul a:hover,nav ul a.on{color:var(--l)}
nav .btn{padding:10px 18px;font-size:14px}
/* hero */
.hero{padding:72px 0 80px}
.lab{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;color:var(--l);margin-bottom:22px}
.lab::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.hero h1{font-size:clamp(36px,5.8vw,76px);line-height:1;letter-spacing:-.038em;max-width:900px}
.hero .sub{margin:22px 0 30px;font-size:clamp(17px,2vw,19px);max-width:560px;color:#d6d6da}
/* workflow component */
.flow{display:flex;gap:18px;margin-top:56px;padding:26px;border:1px solid var(--dline);border-radius:22px;background:var(--k2)}
.nd{flex:1;min-width:0;position:relative;background:var(--k);border:1px solid var(--dline);border-radius:14px;padding:14px 12px;animation:lit 1.4s ease-out;animation-delay:calc(var(--i)*.4s + .3s)}
.nd b{display:block;font:600 13.5px Sora;color:#fff;letter-spacing:-.01em}
.nd span{display:block;font-size:12px;color:var(--dmute);margin-top:5px;line-height:1.35}
.nd::after{content:"";position:absolute;left:100%;top:50%;width:18px;height:2px;background:var(--l);opacity:.5}
.nd:last-child::after{display:none}
.nd.ai{border-color:var(--l);box-shadow:0 0 0 4px #C7FF3F1a}.nd.ai b{color:var(--l)}
@keyframes lit{0%,100%{border-color:var(--dline);box-shadow:none}30%{border-color:var(--l);box-shadow:0 0 0 4px #C7FF3F22}}
.cap{margin-top:14px;font-size:13px;color:var(--dmute)}
/* statement */
.stmt h2{font-size:clamp(30px,5.2vw,62px);line-height:1.05;letter-spacing:-.035em;max-width:980px}
.stmt p{margin:22px 0 28px;font-size:18px;color:var(--mute);max-width:560px}
.chips{display:flex;flex-wrap:wrap;gap:10px}
.chips span{padding:9px 16px;border-radius:99px;background:#fff;border:1px solid var(--line);font-size:14.5px;font-weight:500}
/* bento */
.bento{display:grid;grid-template-columns:repeat(6,1fr);gap:18px}
.bc{border-radius:22px;padding:28px;background:#fff;border:1px solid var(--line);position:relative;overflow:hidden}
.bc h3{font-size:20px;margin-bottom:10px}.bc p{color:var(--mute);max-width:430px;font-size:15.5px}
.s4{grid-column:span 4}.s3{grid-column:span 3}.s2{grid-column:span 2}
.bc.dk{background:var(--k);border-color:var(--k);color:#fff;min-height:250px}.bc.dk p{color:var(--dmute)}
.bc .tag{display:inline-block;font:600 12px Inter;color:var(--k);background:var(--l);padding:5px 12px;border-radius:99px;margin-bottom:16px}
.mini{display:flex;align-items:center;gap:10px;margin-top:24px;flex-wrap:wrap}
.mini b{font:500 13px Inter;padding:10px 14px;border-radius:12px;border:1px solid var(--dline);background:#16161a;color:#fff}.mini b.a{border-color:var(--l)}
.mini s{width:20px;height:2px;background:var(--l);opacity:.6;text-decoration:none}
/* compare */
.cmp{border-radius:22px;overflow:hidden;border:1px solid var(--line)}
.ch,.cr{display:grid;grid-template-columns:1fr 1fr}
.ch div{padding:18px 28px;font:600 17px Sora}.ch div:first-child{background:var(--g);color:var(--mute)}.ch div:last-child{background:var(--k);color:var(--l)}
.cr div{padding:20px 28px;display:flex;gap:14px;align-items:flex-start;font-size:15.5px;border-top:1px solid var(--line)}
.cr div:first-child{background:#fff;color:var(--mute)}.cr div:last-child{background:var(--k2);color:#e8e8ea;border-top-color:var(--dline)}
.cr div::before{flex:none;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font:700 12px Inter;margin-top:1px}
.cr div:first-child::before{content:"✕";background:var(--g);color:#8a8c88}
.cr div:last-child::before{content:"✓";background:var(--l);color:var(--k)}
.fine{margin-top:20px;font-size:14px;color:var(--mute)}
/* use cases */
.uc{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.u{border:1px solid var(--dline);border-radius:20px;padding:26px;background:var(--k);display:flex;flex-direction:column}
.u h3{font-size:19px;color:#fff;margin-bottom:8px}.u p{font-size:15px;margin-bottom:18px}
.u .fl{margin-top:auto;display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-size:12.5px;color:#d8d8dc}
.u .fl i{font-style:normal;padding:4px 10px;border-radius:99px;background:#1c1c20;border:1px solid var(--dline)}.u .fl i.a{border-color:var(--l);color:var(--l)}.u .fl em{font-style:normal;color:#555}
/* badges */
.bd{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.b{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;display:flex;gap:16px;align-items:flex-start}
.b i{flex:none;width:12px;height:12px;border-radius:50%;background:var(--k);margin-top:7px;box-shadow:0 0 0 4px var(--l)}
.b h3{font-size:18px;margin-bottom:4px}.b p{font-size:14.5px;color:var(--mute)}
/* process */
.jr{display:grid;grid-template-columns:repeat(5,1fr);counter-reset:s}
.st{padding:0 14px 0 0;position:relative;counter-increment:s}
.st .dot{width:38px;height:38px;border-radius:50%;background:var(--k2);border:2px solid var(--dline);display:grid;place-items:center;margin-bottom:16px;position:relative;z-index:1;font:600 13px Sora;color:var(--l)}
.st .dot::before{content:counter(s)}
.st::after{content:"";position:absolute;left:46px;right:6px;top:18px;height:2px;background:linear-gradient(90deg,var(--l),#2a2a2e)}
.st:last-child::after{display:none}
.st h4{font-size:17px;margin-bottom:6px;color:#fff}.st p{font-size:14.5px}
/* faq */
.faq{max-width:780px}
details{border-top:1px solid var(--line);padding:20px 0}details:last-child{border-bottom:1px solid var(--line)}
summary{cursor:pointer;font:600 18px Sora;list-style:none;display:flex;justify-content:space-between;gap:16px}
summary::-webkit-details-marker{display:none}summary::after{content:"+";font-size:24px;line-height:1;transition:transform .2s}
details[open] summary::after{transform:rotate(45deg)}
details p{margin-top:12px;color:var(--mute);max-width:640px}
/* cta */
.cta{background:var(--l);color:var(--k);padding:96px 0}
.cta h2{font-size:clamp(32px,5.8vw,66px);letter-spacing:-.035em;max-width:820px}
.cta p{margin:18px 0 32px;font-size:18px;max-width:520px;color:#2a3300}
/* footer */
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.ft{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:40px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}
footer h4{font-size:14px;margin-bottom:14px}
footer ul{list-style:none;margin:0;padding:0}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.flow{flex-direction:column;gap:20px;max-width:560px}
.nd{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:14px 16px}.nd span{margin:0;text-align:right}
.nd::after{left:24px;top:100%;width:2px;height:20px}
.bento .s4,.bento .s3{grid-column:span 6}.bento .s2{grid-column:span 3}
.uc,.bd{grid-template-columns:repeat(2,1fr)}
.jr{grid-template-columns:1fr;gap:22px}.st{display:grid;grid-template-columns:38px 1fr;column-gap:16px;padding:0}.st .dot{grid-row:span 2;margin:0}.st::after{display:none}.st h4{margin-top:2px}
.ft{grid-template-columns:1fr 1fr}}
@media(max-width:860px){nav ul{display:none}}
/* mobile */
@media(max-width:600px){
section{padding:64px 0}.wrap{padding:0 20px}.hero{padding-top:56px}
.flow{padding:18px;margin-top:40px}.nd{flex-direction:column;align-items:flex-start;gap:4px}.nd span{text-align:left}
.bento .s2{grid-column:span 6}.bc{padding:24px}
.ch div,.cr div{padding:16px 18px}.ch,.cr{grid-template-columns:1fr}.ch div:last-child{display:none}.ch div:first-child::after{content:" → After";color:var(--l)}
.cr div:last-child{border-top:0}
.uc,.bd{grid-template-columns:1fr}.ctas .btn{width:100%;justify-content:center}.ft{grid-template-columns:1fr}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}}
